    Bug 2005090 - Remove pref mail.inappnotifications.pkceUpgradeForYahooAol and associated code. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D275709

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index 484fe0092f1..f352c118daa 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -1486,11 +1486,6 @@ pref("mail.inappnotifications.refreshInterval", 21600000);
 // Disables all filtering of in-app notifications, useful for testing.
 pref("mail.inappnotifications.bypass-filtering", false);

-// Whether Yahoo/AOL/ATT OAuth user is detected.
-// Used to notify about upcoming changes via in-app notification.
-// TODO: Remove this when PKCE is fully rolled out for Yahoo/AOL/AT&T
-pref("mail.inappnotifications.pkceUpgradeForYahooAol", false);
-
 // Whether Thunderbird is running under Flatpak or Snap.
 // These are set at startup each run so they reflect the current runtime.
 // Used to notify about upcoming changes via in-app notification.
diff --git a/mail/modules/MailMigrator.sys.mjs b/mail/modules/MailMigrator.sys.mjs
index 7886717de25..9be2053d683 100644
--- a/mail/modules/MailMigrator.sys.mjs
+++ b/mail/modules/MailMigrator.sys.mjs
@@ -30,7 +30,7 @@ export var MailMigrator = {
   _migrateUI() {
     // The code for this was ported from
     // mozilla/browser/components/nsBrowserGlue.js
-    const UI_VERSION = 57;
+    const UI_VERSION = 58;
     const UI_VERSION_PREF = "mail.ui-rdf.version";
     let currentUIVersion = Services.prefs.getIntPref(UI_VERSION_PREF, 0);

@@ -414,6 +414,15 @@ export var MailMigrator = {
         );
       }

+      if (currentUIVersion < 58) {
+        // We've already migrated Yahoo/AOL/AT&T accounts to use PKCE
+        // where applicable in OAuth2Module.sys.mjs. We can now remove the
+        // pref that indicates whether such a user was detected.
+        Services.prefs.clearUserPref(
+          "mail.inappnotifications.pkceUpgradeForYahooAol"
+        );
+      }
+
       // Migration tasks that may take a long time are not run immediately, but
       // added to the MigrationTasks object then run at the end.
       //
